(function(){
  const atlas=window.MOOVABLES_SPELL_ICON_ATLAS||{};
  const spells=atlas.spells||{};
  const meta=atlas.meta||{};
  const iconSize=Number(meta.iconSize)||50;
  const cols=Number(meta.atlasColumns||meta.columns)||24;
  const rows=Number(meta.rows)||Math.ceil(Object.keys(spells).length/cols)||1;
  const atlasUrl='assets/spell-icons/'+(meta.atlasFile||'moovables_spell_atlas.webp');
  function slug(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');}
  function find(name){const key=slug(name);return spells[key]||Object.values(spells).find(s=>slug(s.name)===key)||null;}
  function esc(value){return String(value||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  function style(name,size){
    size=Number(size)||22;
    const entry=find(name);
    if(!entry) return '';
    const sourceW=Number(entry.w)||50;
    const scale=size/sourceW;
    return 'background-image:url("'+atlasUrl+'");background-size:'+(cols*iconSize*scale)+'px '+(rows*iconSize*scale)+'px;background-position:-'+((Number(entry.col)*iconSize)*scale)+'px -'+((Number(entry.row)*iconSize)*scale)+'px;';
  }
  function html(name,size,extraClass){
    size=Number(size)||22;
    const entry=find(name);
    const title=entry?entry.name:(name||'Action');
    const styleText=entry?style(name,size):'';
    return '<span class="spell-icon '+(entry?'':'fallback')+' '+(extraClass||'')+'" title="'+esc(title)+'" style="--icon-size:'+size+'px;'+styleText+'">'+(entry?'':'?')+'</span>';
  }
  window.MoovablesSpellIcons={slug,find,style,html,atlasUrl};
})();
